-- new_country_scaffold.py; INSERT OR IGNORE throughout (idempotent).

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'ar-b2b-2015', id, '2015-03-10', 1, 'https://www.argentina.gob.ar/normativa/nacional/resoluci%C3%B3n-3749-2015-244572', 0, '[{"label": "ARCA -- Factura electronica (emision y autorizacion)", "url": "https://www.afip.gob.ar/fe/emision-autorizacion/sujetos.asp"}]', NULL, 'b2b' FROM countries WHERE code = 'AR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-b2b-2015', 'en', 'Mandatory e-invoicing for VAT-registered taxpayers (RG 3749/2015)', 'AFIP''s General Resolution 3749/2015 made electronic invoicing mandatory for taxpayers registered for VAT and for VAT-exempt subjects, building on the voluntary system Argentina had run since 2003. Each invoice is submitted to AFIP (now ARCA) for real-time validation and assigned a CAE (Codigo de Autorizacion Electronico) before it can be delivered to the buyer -- a clearance model, not post-audit reporting.', '["Register for a digital tax certificate with AFIP/ARCA to request CAE authorization", "Confirm invoicing software or the ''Comprobantes en Linea'' web portal generates XML in AFIP''s schema"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'ar-b2b-2019-universal', id, '2019-04-01', 0, 'http://biblioteca.afip.gob.ar/dcp/REAG01004290_2018_08_02', 1, '[{"label": "ARCA -- Factura electronica (emision y autorizacion)", "url": "https://www.afip.gob.ar/fe/emision-autorizacion/sujetos.asp"}]', NULL, 'b2b' FROM countries WHERE code = 'AR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-b2b-2019-universal', 'en', 'Mandate goes universal -- all monotributistas and final-consumer sales included (RG 4290/2018)', 'RG 4290/2018 completed the rollout begun with VAT-exempt subjects on 1 January 2019: from 1 April 2019, every monotributista (Argentina''s simplified small-taxpayer regime) had to replace paper invoicing with electronic invoices or a fiscal controller -- including sales to final consumers, with mobile-app invoicing required for transactions completed at the customer''s premises. This is the point at which e-invoicing became effectively universal across Argentina''s taxpayer base, with only the smallest social-monotax categories retaining a manual option.', '["Confirm monotributista and small-business invoicing workflows issue electronic Type B (final-consumer) invoices, not paper", "Enable mobile/app-based invoicing for any at-customer-premises sales"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'ar-format-2025', id, '2025-04-15', 0, 'https://www.boletinoficial.gov.ar/detalleAviso/primera/318374/20241218', 1, '[{"label": "ARCA -- Factura electronica (emision y autorizacion)", "url": "https://www.afip.gob.ar/fe/emision-autorizacion/sujetos.asp"}]', NULL, 'none' FROM countries WHERE code = 'AR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-format-2025', 'en', 'Updated web services and itemized VAT/FX disclosure become mandatory (RG 5616/2024)', 'RG 5616/2024 (Boletin Oficial 18 December 2024) updated ARCA''s technical specifications for electronic invoicing: from 15 April 2025, issuers must use the revised web services, the ''Comprobantes en Linea'' portal, and the mobile app in their updated form, and invoices must itemize VAT by rate and disclose the foreign-currency exchange rate used. A format and disclosure upgrade to the existing CAE clearance model, not a new invoicing-scope requirement -- the same treatment this tracker gives Spain''s VeriFactu.', '["Update invoicing integrations to the RG 5616/2024 web-service specification before relying on the older schema", "Confirm multi-currency invoices display itemized VAT and the FX rate applied"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'ar-sector-expansion-2026', id, '2026-07-01', 0, 'https://www.boletinoficial.gob.ar/detalleAviso/primera/338446/20260213', 1, '[{"label": "ARCA -- Factura electronica (emision y autorizacion)", "url": "https://www.afip.gob.ar/fe/emision-autorizacion/sujetos.asp"}]', NULL, 'b2b' FROM countries WHERE code = 'AR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-sector-expansion-2026', 'en', 'Sector expansion and consolidated monthly invoicing (RG 5824/2026)', 'RG 5824/2026 (Boletin Oficial 13 February 2026) broadened the categories of taxpayers required to issue electronic invoices -- bringing in, among others, financial entities, insurers, credit-card administrators, prepaid health plans, and educational institutions -- and introduced a ''liquidacion electronica mensual'' letting high-volume issuers in those sectors consolidate a client''s transactions into one monthly electronic invoice rather than issuing one per transaction. A new ARS 10 million threshold also requires final-consumer identification on larger sales, closing the anonymous-invoice gap for high-value transactions. Effective for operations from 1 July 2026.', '["Confirm newly-in-scope sectors (financial services, insurance, prepaid health, education) have onboarded to electronic invoicing", "Evaluate the monthly consolidated settlement voucher for high-volume client billing"]');
